function elementsOf(part: string): Element[] {
  return Object.entries(FITS[part]).map(([name, fit], i) => ({ id: i + 1, kind: fit.kind, name, fit, color: '#888888', status: 'done', visible: true, source: { type: 'picked' } }) as unknown as Element)
}

describe('Align by Coordinate System with many primitives lands where QUICKSURFACE does (align sweep 3)', () => {
  it.each(CASES.map((c) => [c.id, c] as const))('%s', (_, c) => {
    const elements = elementsOf(c.part)
    const id = (name: string | null) => (name === null ? null : alignmentReferences(elements).find((e) => e.name === name)?.id ?? null)
    const ad: AlignDraft = {
      primary: id(c.p), primaryPicks: [], primaryPickNormals: [], primaryAxis: c.pa,
      secondary: id(c.s), secondaryPicks: [], secondaryAxis: c.sa,
      origin: id(c.t), originPicks: [], pickSlot: null,
      tertiaryAxis: c.ta ?? undefined, tertiaryFlip: c.tf,
    }
    const { preview, error } = alignmentPreview(ad, elements, 1000, [999, 999, 999])
    expect(error).toBeNull()
    Array.from(preview!.rigid.r).forEach((v, i) => expect(Math.abs(v - c.r[i])).toBeLessThan(2e-4))
    Array.from(preview!.rigid.t).forEach((v, i) => expect(Math.abs(v - c.t3[i])).toBeLessThan(2e-3))
  })
})
